package com.university.scheduler.ui;
import com.university.scheduler.dao.UiRepository;import com.university.scheduler.model.Faculty;import javafx.collections.*;import javafx.geometry.*;import javafx.scene.Parent;import javafx.scene.control.*;import javafx.scene.layout.*;
public class FacultyView{
 private final ObservableList<Faculty> rows=FXCollections.observableArrayList();private final TableView<Faculty> table=new TableView<>();
 public Parent getView(){VBox root=UiSupport.page("Faculty Management","Manage faculty records stored in the OptiSchedule database.");TextField search=UiSupport.field("Search by ID, name or department");Button add=new Button("+ Add Faculty"),refresh=new Button("Refresh");add.getStyleClass().add("primary-button");HBox bar=new HBox(10,search,refresh,add);HBox.setHgrow(search,Priority.ALWAYS);table.getColumns().addAll(UiSupport.col("Faculty ID",Faculty::getFacultyId),UiSupport.col("Name",f->safe(f.getFacultyName())),UiSupport.col("Department",f->safe(f.getDepartment())),UiSupport.col("Max Hours / Week",f->String.valueOf(f.getMaxHoursPerWeek())));UiSupport.style(table);table.setItems(rows);
 TableColumn<Faculty,Void> act=new TableColumn<>("Actions");act.setCellFactory(c->new TableCell<>(){Button edit=new Button("Edit"),del=new Button("Delete");HBox box=new HBox(6,edit,del);{edit.setOnAction(e->dialog(getTableView().getItems().get(getIndex())));del.setOnAction(e->{Faculty f=getTableView().getItems().get(getIndex());if(UiSupport.confirm("Delete faculty "+f.getFacultyId()+"?"))try{UiRepository.deleteFaculty(f.getFacultyId());load();}catch(Exception ex){UiSupport.error("Could not delete faculty",ex);}});}protected void updateItem(Void v,boolean empty){super.updateItem(v,empty);setGraphic(empty?null:box);}});table.getColumns().add(act);search.textProperty().addListener((o,a,b)->table.setItems(rows.filtered(f->(f.getFacultyId()+safe(f.getFacultyName())+safe(f.getDepartment())).toLowerCase().contains(b.toLowerCase()))));add.setOnAction(e->dialog(null));refresh.setOnAction(e->load());root.getChildren().addAll(bar,table);VBox.setVgrow(table,Priority.ALWAYS);load();return root;}
 private static String safe(String s){return s==null?"":s;}private void load(){try{rows.setAll(UiRepository.faculty());table.setItems(rows);}catch(Exception e){UiSupport.error("Database connection failed while loading faculty",e);}}
 private void dialog(Faculty old){Dialog<ButtonType>d=new Dialog<>();d.setTitle(old==null?"Add Faculty":"Edit Faculty");ButtonType save=new ButtonType("Save",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);TextField id=UiSupport.field("Faculty ID"),name=UiSupport.field("Faculty name"),dept=UiSupport.field("Department"),hours=UiSupport.field("Maximum hours per week");if(old!=null){id.setText(old.getFacultyId());id.setDisable(true);name.setText(safe(old.getFacultyName()));dept.setText(safe(old.getDepartment()));hours.setText(String.valueOf(old.getMaxHoursPerWeek()));}else hours.setText("18");GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);g.addRow(0,new Label("Faculty ID"),id);g.addRow(1,new Label("Name"),name);g.addRow(2,new Label("Department"),dept);g.addRow(3,new Label("Max hours/week"),hours);d.getDialogPane().setContent(g);d.showAndWait().ifPresent(b->{if(b==save)try{int h=Integer.parseInt(hours.getText().trim());if(id.getText().isBlank()||h<0)throw new IllegalArgumentException("Enter a faculty ID and non-negative weekly limit.");UiRepository.saveFaculty(new Faculty(id.getText().trim(),name.getText().trim(),dept.getText().trim(),h),old!=null);load();}catch(Exception ex){UiSupport.error("Could not save faculty",ex);}});}
}
